; ============================================================================
; tiles_bg — 8x8 background tileset (WazHack/ZX side-view scene)
; Generated by tools/gfx_convert.py on 2026-09-24
; Source        : assets/gfx/sprites/grid/tiles_bg.grid
;                 DRAFT: assets/gfx/source/draft3_frames.html
; Layout        : 7 tiles x 8 bitmap bytes (MSB=left), row-major
;                 parallel attr table, one attribute byte per tile
; Clash         : each tile is one paper+ink — clash-legal by construction
; Intended use  : PROTO room tiles via draw_cell (prototype.md §3.3/§4.1)
; ============================================================================
tiles_bg:
tiles_bg_platform:
        DEFB $FF,$10,$10,$10,$FF,$01,$01,$01    ; platform
tiles_bg_platform_end_l:
        DEFB $FF,$90,$90,$90,$FF,$81,$81,$81    ; platform_end_l
tiles_bg_platform_end_r:
        DEFB $FF,$11,$11,$11,$FF,$01,$01,$01    ; platform_end_r
tiles_bg_wall:
        DEFB $FF,$88,$88,$88,$FF,$22,$22,$22    ; wall
tiles_bg_ladder_l:
        DEFB $60,$7F,$60,$60,$60,$7F,$60,$60    ; ladder_l
tiles_bg_ladder_m:
        DEFB $00,$FF,$00,$00,$00,$FF,$00,$00    ; ladder_m
tiles_bg_ladder_r:
        DEFB $06,$FE,$06,$06,$06,$FE,$06,$06    ; ladder_r

tiles_bg_attr:
        DEFB $0F    ; platform ink=white paper=blue bright=0
        DEFB $0F    ; platform_end_l ink=white paper=blue bright=0
        DEFB $0F    ; platform_end_r ink=white paper=blue bright=0
        DEFB $01    ; wall     ink=blue paper=black bright=0
        DEFB $02    ; ladder_l ink=red paper=black bright=0
        DEFB $02    ; ladder_m ink=red paper=black bright=0
        DEFB $02    ; ladder_r ink=red paper=black bright=0
tiles_bg_count EQU 7
